console.log("RockCommerceAlpine");document.addEventListener("alpine:init",()=>{Alpine.data("RockCommerceAlpine",()=>({init(){RockCommerceOLD.addComponent(this);RockCommerceOLD.config=JSON.parse(this.$rcattr("data-config")||"{}");document.dispatchEvent(new CustomEvent("RockCommerce:ready"))},}))});document.addEventListener("alpine:init",()=>{Alpine.magic("rcpid",(el)=>{const c=RockCommerceOLD.getComponent(el);return c.$rcattr("rc-pid")});Alpine.magic("rcattr",(el)=>{const c=RockCommerceOLD.getComponent(el);return(attr)=>c.$root.getAttribute(attr)});Alpine.magic("rctype",(el)=>{const c=RockCommerceOLD.getComponent(el);return c.$el.getAttribute("x-data")})})